// EXP-006 - Hongdae entrance, rainy night. Zero external assets: geometry, textures and sound are generated by code.
import * as THREE from 'three';
import { timeUniform, W, clamp, lerp } from './util.js';
import { buildCity, makeEnvironment, makeSky } from './city.js';
import { GlowPoints, Steam, viewUniforms } from './glow.js';
import { WetStreaks, Ripples } from './wet.js';
import { Rain } from './rain.js';
import { Signal, Traffic } from './traffic.js';
import { Crowd } from './crowd.js';
import { CameraRig } from './camera.js';
import { RainAudio } from './audio.js';

const $ = id => document.getElementById(id);
const stage = $('exp6-stage'), canvas = $('exp6-canvas'), statusEl = $('exp6-status'), loading = $('exp6-loading'), loadText = $('exp6-loading-text');
const btn = { sound: $('exp6-sound'), cam: $('exp6-camera'), pause: $('exp6-pause'), full: $('exp6-full') };
const reducedMQ = matchMedia('(prefers-reduced-motion: reduce)');
const say = msg => { statusEl.textContent = msg; };
const nextFrame = () => new Promise(r => requestAnimationFrame(() => r()));

function fail(msg) {
  loading.hidden = false; loading.classList.add('is-error'); loadText.textContent = msg; say(msg);
  for (const b of Object.values(btn)) if (b) b.disabled = true;
}

async function main() {
  let renderer;
  try { renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' }); }
  catch (e) { fail('이 브라우저에서는 WebGL을 시작할 수 없어 장면을 그릴 수 없습니다.'); return; }
  const gl = renderer.getContext();
  const maxPoint = (gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE) || [1, 64])[1];
  renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.15;
  renderer.setClearColor(0x1b1329);
  let pixelRatio = Math.min(window.devicePixelRatio || 1, innerWidth < 700 ? 1.5 : 1.75);
  const maxPixelRatio = pixelRatio;

  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x1b1329, 0.011);
  const camera = new THREE.PerspectiveCamera(52, 16 / 9, 0.1, 900);

  const step = async (label, fn) => { loadText.textContent = label; await nextFrame(); return fn(); };

  const sky = makeSky(); scene.add(sky.mesh);
  scene.environment = await step('가로등과 네온의 반사 환경을 계산하는 중…', () => makeEnvironment(renderer));

  const hemi = new THREE.HemisphereLight(0x5766b0, 0x1f1330, 0.95); scene.add(hemi);
  const moon = new THREE.DirectionalLight(0x7f94d8, 0.45); moon.position.set(-18, 40, 14); scene.add(moon);
  const pink = new THREE.PointLight(0xff2d95, 90, 30, 2); pink.position.set(-8.5, 6.5, 14); scene.add(pink);
  const cyan = new THREE.PointLight(0x19e6ff, 80, 30, 2); cyan.position.set(8.5, 5.5, -2); scene.add(cyan);

  const glow = new GlowPoints(700), wet = new WetStreaks(520), steamSpots = [];
  const city = await step('건물과 간판 텍스처를 Canvas로 그리는 중…', () => buildCity({ scene, glow, wet, steamSpots }));
  const signal = new Signal(29.2);
  const traffic = await step('자동차와 사람들을 세우는 중…', () => new Traffic({ scene, glow, wet, signal }));
  const crowd = new Crowd({ scene, city, signal });
  glow.commit();
  scene.add(glow.points, wet.mesh);
  const ripples = new Ripples(900); scene.add(ripples.mesh);
  const steam = new Steam(steamSpots); scene.add(steam.points);
  const rain = new Rain(7500); scene.add(rain.points);

  const audio = new RainAudio();
  const rig = new CameraRig(camera, canvas, { obstacles: city.obstacles, reduced: reducedMQ.matches });

  // ---------------------------------------------------------------- sizing
  function resize() {
    const w = Math.max(2, stage.clientWidth), h = Math.max(2, stage.clientHeight);
    renderer.setPixelRatio(pixelRatio); renderer.setSize(w, h, false);
    camera.aspect = w / h; applyFov(true);
  }
  let fovNow = 52;
  function applyFov(snap) {
    const aspect = camera.aspect, base = rig.mode === 'walk' ? 62 : 52, target = Math.min(84, base + Math.max(0, 1.25 - aspect) * 42);
    fovNow = snap ? target : lerp(fovNow, target, 0.06);
    if (Math.abs(camera.fov - fovNow) > 0.01 || snap) { camera.fov = fovNow; camera.updateProjectionMatrix(); }
    viewUniforms.uScale.value = renderer.domElement.height / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
    viewUniforms.uMax.value = Math.min(maxPoint, 190);
  }
  new ResizeObserver(resize).observe(stage); resize();

  // ---------------------------------------------------------------- UI
  const setPressed = (b, on) => b.setAttribute('aria-pressed', String(on));
  function syncCamButton() {
    const auto = rig.mode === 'auto';
    btn.cam.textContent = auto ? '카메라: 자동 투어' : '카메라: 직접 걷기'; setPressed(btn.cam, !auto);
    stage.classList.toggle('is-walk', !auto); canvas.style.touchAction = auto ? 'pan-y' : 'none';
  }
  rig.onModeChange = mode => { syncCamButton(); say(mode === 'auto' ? '카메라가 자동 투어로 돌아갑니다.' : '직접 걷기 모드입니다. WASD 또는 방향키로 이동하고 드래그로 둘러보세요.'); };
  syncCamButton();
  btn.cam.addEventListener('click', () => rig.setMode(rig.mode === 'auto' ? 'walk' : 'auto'));

  btn.sound.addEventListener('click', async () => {
    if (!audio.on) {
      const ok = await audio.enable();
      if (!ok) { say('이 브라우저는 Web Audio를 지원하지 않습니다.'); return; }
      btn.sound.textContent = '소리 끄기'; setPressed(btn.sound, true); say('빗소리를 직접 합성해 재생합니다.');
    } else { audio.disable(); btn.sound.textContent = '소리 켜기'; setPressed(btn.sound, false); say('소리를 껐습니다.'); }
  });
  let paused = false;
  btn.pause.addEventListener('click', () => { paused = !paused; btn.pause.textContent = paused ? '장면 재생' : '장면 멈춤'; setPressed(btn.pause, paused); say(paused ? '비, 사람, 자동차의 시간이 멈췄습니다. 카메라는 움직일 수 있습니다.' : '장면이 다시 흐릅니다.'); });
  if (stage.requestFullscreen) {
    btn.full.addEventListener('click', () => { document.fullscreenElement ? document.exitFullscreen() : stage.requestFullscreen().catch(() => say('전체 화면을 열 수 없습니다.')); });
    document.addEventListener('fullscreenchange', () => { btn.full.textContent = document.fullscreenElement ? '전체 화면 닫기' : '전체 화면'; setPressed(btn.full, !!document.fullscreenElement); });
  } else btn.full.hidden = true;

  // keyboard: only while the stage has focus, so page scrolling keeps working elsewhere
  const MOVE = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight']);
  stage.addEventListener('keydown', e => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (MOVE.has(e.code)) { if (rig.mode === 'auto' && !e.code.startsWith('Shift')) rig.setMode('walk'); rig.keys.add(e.code); e.preventDefault(); }
    else if (e.code === 'KeyM') btn.sound.click(); else if (e.code === 'KeyC') btn.cam.click(); else if (e.code === 'KeyP') btn.pause.click();
  });
  stage.addEventListener('keyup', e => rig.keys.delete(e.code));
  stage.addEventListener('blur', () => rig.keys.clear());
  // drag to look
  let drag = null;
  canvas.addEventListener('pointerdown', e => { if (e.button > 0) return; drag = { id: e.pointerId, x: e.clientX, y: e.clientY, total: 0 }; canvas.setPointerCapture(e.pointerId); stage.focus({ preventScroll: true }); });
  canvas.addEventListener('pointermove', e => {
    if (!drag || e.pointerId !== drag.id) return;
    const dx = e.clientX - drag.x, dy = e.clientY - drag.y; drag.x = e.clientX; drag.y = e.clientY; drag.total += Math.abs(dx) + Math.abs(dy);
    if (drag.total > 6) rig.look(dx, e.pointerType === 'touch' && rig.mode === 'auto' ? 0 : dy);
  });
  const endDrag = e => { if (drag && e.pointerId === drag.id) drag = null; };
  canvas.addEventListener('pointerup', endDrag); canvas.addEventListener('pointercancel', endDrag);
  // on-screen pad for touch
  stage.querySelectorAll('[data-pad]').forEach(b => {
    const set = v => { const k = b.dataset.pad; if (rig.mode === 'auto') rig.setMode('walk'); if (k === 'f') rig.pad.f = v; if (k === 'b') rig.pad.f = -v; if (k === 'l') rig.pad.t = v; if (k === 'r') rig.pad.t = -v; };
    b.addEventListener('pointerdown', e => { e.preventDefault(); b.setPointerCapture(e.pointerId); set(1); });
    for (const ev of ['pointerup', 'pointercancel', 'lostpointercapture']) b.addEventListener(ev, () => set(0));
    b.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); set(1); } });
    b.addEventListener('keyup', e => { if (e.key === 'Enter' || e.key === ' ') set(0); });
  });
  reducedMQ.addEventListener?.('change', () => { if (reducedMQ.matches) rig.setMode('walk'); rig.reduced = reducedMQ.matches; });

  // ---------------------------------------------------------------- loop state
  let visible = true, simT = 0, last = performance.now(), nextFlash = 9 + Math.random() * 6, flashAt = -1, chimeNear = false, lastCarState = '', lastPedState = '';
  new IntersectionObserver(es => { visible = es[0].isIntersecting; audio.setActive(visible && !document.hidden); }, { threshold: 0.05 }).observe(stage);
  document.addEventListener('visibilitychange', () => audio.setActive(visible && !document.hidden));

  const FLASH = [[0, 1], [0.1, 0.25], [0.17, 0.9], [0.34, 0.4]];
  const flashLevel = tau => { let a = 0; for (const [t0, amp] of FLASH) if (tau > t0) a += amp * Math.exp(-(tau - t0) * 8); return Math.min(1, a); };

  // adaptive resolution: keep the frame rate usable on weaker GPUs
  let acc = 0, frames = 0;
  const stats = { fps: 0, calls: 0, triangles: 0, pixelRatio };

  function frame(now) {
    requestAnimationFrame(frame);
    if (!visible || document.hidden) { last = now; return; }
    const rdt = Math.min(0.05, (now - last) / 1000); last = now;
    const dt = paused ? 0 : rdt;
    simT += dt; timeUniform.value = simT + 40;
    rig.update(rdt);
    applyFov(false);
    signal.update(dt);
    traffic.update(dt, camera.position);
    crowd.update(dt, simT, camera.position);
    city.update(simT);

    // signals
    const carState = signal.amber ? 'a' : signal.carRed ? 'r' : 'g';
    if (carState !== lastCarState) { lastCarState = carState; const hex = carState === 'g' ? 0x35ff7a : carState === 'a' ? 0xffb020 : 0xff2a2a; city.signals.car.forEach(i => glow.setColor(i, hex, 1.4)); }
    const pedState = signal.pedWalk ? (signal.pedBlink && Math.floor(simT * 2.5) % 2 ? 'o' : 'g') : 'r';
    if (pedState !== lastPedState) { lastPedState = pedState; const hex = pedState === 'g' ? 0x35ff7a : pedState === 'o' ? 0x103018 : 0xff2a2a; city.signals.ped.forEach(i => glow.setColor(i, hex, 1.3)); }

    // lightning
    simT >= nextFlash && flashAt < 0 && (flashAt = simT, nextFlash = simT + 22 + Math.random() * 30, setTimeout(() => audio.thunder(0.6 + Math.random() * 0.6), 700 + Math.random() * 1800));
    let flash = 0;
    if (flashAt >= 0) { const tau = simT - flashAt; flash = reducedMQ.matches ? 0 : flashLevel(tau); if (tau > 1.8) flashAt = -1; }
    sky.uniforms.uFlash.value = flash; hemi.intensity = 0.95 + flash * 3.2; scene.fog.color.setRGB(0.0103 + flash * 0.1, 0.0065 + flash * 0.11, 0.0225 + flash * 0.17);

    // convenience-store door chime
    const ds = Math.hypot(camera.position.x - city.zones.store.x, camera.position.z - city.zones.store.z);
    if (ds < 7 && !chimeNear) { chimeNear = true; audio.chime(); } else if (ds > 12) chimeNear = false;

    sky.mesh.position.copy(camera.position);
    wet.update(camera); ripples.update(camera); rain.update(camera);
    if (audio.on) audio.update({ carDist: traffic.nearest.d, carSpeed: traffic.nearest.v, clubDist: Math.hypot(camera.position.x - city.clubDoor.x, camera.position.z - city.clubDoor.z) });

    renderer.render(scene, camera);

    acc += rdt; frames++;
    if (frames >= 45) {
      const avg = acc / frames; stats.fps = Math.round(1 / avg); acc = 0; frames = 0;
      if (!paused || true) {
        if (avg > 1 / 40 && pixelRatio > 0.7) { pixelRatio = Math.max(0.7, pixelRatio * 0.85); resize(); }
        else if (avg < 1 / 56 && pixelRatio < maxPixelRatio) { pixelRatio = Math.min(maxPixelRatio, pixelRatio * 1.07); resize(); }
      }
      stats.pixelRatio = +pixelRatio.toFixed(2);
    }
    stats.calls = renderer.info.render.calls; stats.triangles = renderer.info.render.triangles;
  }
  requestAnimationFrame(frame);
  window.__exp006 = { THREE, renderer, scene, camera, rig, stats, city, signal, traffic, crowd, audio, sky, get simT() { return simT; }, setPaused: v => { paused = v; }, skipTo: t => { simT = t; } };

  loading.hidden = true; stage.classList.add('is-ready');
  say('장면이 준비되었습니다. 카메라는 자동 투어 중입니다.');
}

main().catch(err => { console.error(err); fail('장면을 만드는 중 오류가 발생했습니다: ' + (err && err.message ? err.message : err)); });
